<?php $pageTitle = $type === 'page' ? 'Pages' : 'Posts'; $base = $type === 'page' ? 'pages' : 'posts'; ?>
<div class="row between"><p class="muted">Manage <?= e($pageTitle) ?> and publication status.</p><a class="btn primary" href="/admin/<?= e($base) ?>/create">Create <?= e($type) ?></a></div><div class="card"><table class="table"><thead><tr><th>Title</th><th>Slug</th><th>Status</th><th>Author</th><th>Updated</th><th></th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><strong><?= e($item['title']) ?></strong></td><td class="code"><?= e($item['slug']) ?></td><td><?= e($item['status']) ?></td><td><?= e($item['author_name']) ?></td><td><?= e($item['updated_at']) ?></td><td><div class="row"><a class="btn small" href="/admin/<?= e($base) ?>/<?= (int) $item['id'] ?>/edit">Edit</a><form method="post" action="/admin/<?= e($base) ?>/<?= (int) $item['id'] ?>/delete" onsubmit="return confirm('Delete this item?')"><?= csrf_field() ?><button class="btn small danger" type="submit">Delete</button></form></div></td></tr><?php endforeach; ?><?php if (!$items): ?><tr><td colspan="6" class="muted">Nothing here yet.</td></tr><?php endif; ?></tbody></table></div>
